import os, glob, re

# Load all grids
d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read().replace('\\n', '\n')
G = {}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
    k, h, w = m[1], int(m[2]), int(m[3])
    rows = [r.split() for r in t[m.end():].split('\n')[:h]]
    if k not in G and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
        G[k] = [[int(x) for x in r] for r in rows]

# Verify my hypothesis on demo pair 1
inp = G['Demo pair 1']
out = [['0' for _ in range(9)] for _ in range(21)]
for r in range(21):
    for c in range(9):
        if inp[r][c] == 5:
            # Check if has a 5-nei
            has_5_n = c > 0 and inp[r][c-1] == 5
            has_5_s = c < 8 and inp[r][c+1] == 5
            if has_5_n or has_5_s:
                out[r][c] = '7'
        elif inp[r][c] == 7:
            # Check if has 5 below
            if r < 20 and inp[r+1][c] == 5:
                out[r][c] = '7'

# Check match
match_all = all(inp[r][c] == out[r][c] for r in range(21) for c in range(9))
print("Match all demo outputs (hypothesis):", match_all)
if not match_all:
    mismatches = []
    for r in range(21):
        for c in range(9):
            if inp[r][c] != out[r][c]:
                mismatches.append(((r,c), inp[r][c], out[r][c]))
    print("Mismatches count:", len(mismatches))
    print("Sample mismatches:", mismatches[:10])

